        for line in block['lines']:
            for span in line['spans']:
                text = span['text']
                if 'arXiv' in text or 'eess' in text or 'Sep 2025' in text or '2509' in text:
                    print(span.get('dir'), span['bbox'], repr(text))
doc.close()
